// A4988: one pulse on STEP is one step, DIR picks the way
const int STEP = 3, DIR = 4;           // STEP and DIR
const int MS1 = 5, MS2 = 6, MS3 = 7;   // MS1, MS2 and MS3 pick the step size

// n pulses, each one HIGH then LOW for halfUs microseconds
void pulses(long n, int halfUs) {
  for (long i = 0; i < n; i++) {
    digitalWrite(STEP, HIGH); delayMicroseconds(halfUs);
    digitalWrite(STEP, LOW); delayMicroseconds(halfUs);
  }
}

void setup() {
  for (int p = 3; p <= 7; p++) pinMode(p, OUTPUT);
  Serial.begin(9600);
  digitalWrite(MS1, LOW); digitalWrite(MS2, LOW); digitalWrite(MS3, LOW);   // all low: full step, 200 steps a turn
  digitalWrite(DIR, HIGH);
  delay(1);                     // the chip needs 1 ms after waking before the first step
}

void loop() {
  pulses(200, 2500);
  Serial.println("full step: 200 steps = 1 turn");
  delay(1000);
}

